        "title": "العزل الحراري بالرياض: الأسعار المعتمدة والتكلفة الشاملة لعام 2025",
        "excerpt": "دليل هندسي متخصص ومفصل يوضح كل ما تحتاج معرفته حول العزل الحراري في أحياء مدينة الرياض وفق أحدث المعايير والمواصفات.",
        "content": [
          "يُعد العزل الحراري من أهم ركائز البناء وحماية العقارات في مدينة الرياض، حيث تصل درجات الحرارة صيفاً إلى 50 درجة مئوية وتحدث تقلبات مناخية سريعة في الشتاء.",
          "نعتمد في شركة النبلاء أعلى معايير الجودة العالمية باستخدام مواد عزل أمريكية وأوروبية معتمدة ومطابقة تماماً لكود البناء السعودي SBC 601 و 602.",
          "يتم تنفيذ العمل تحت إشراف هندسي متكامل وفريق فني مدرب، مع إجراء فحص حراري بكاميرات الأشعة تحت الحمراء واختبار غمر مائي للتأكد من صفر تسربات بنسبة 100%."
        ],
